
// Quilt Bee - single-file static server (Node built-ins only).
// Site files are embedded base64 below; generated by gen_server.py.
const http = require("http");
const FILES = {"/favicon.svg": {"ct": "image/svg+xml", "b64": ""}, "/og.jpg": {"ct": "image/jpeg", "b64": ""}, "/x-banner.jpg": {"ct": "image/jpeg", "b64": ""}, "/index.html": {"ct": "text/html; charset=utf-8", "b64": ""}, "/assets/styles-CsLmbk1q.css": {"ct": "text/css; charset=utf-8", "b64": ""}, "/assets/index-CBey6KVZ.js": {"ct": "text/javascript; charset=utf-8", "b64": ""}, "/assets/routes-DsIcuixh.js": {"ct": "text/javascript; charset=utf-8", "b64": "aW1wb3J0e3QgYXMgZX1mcm9tIi4vYXBwLUVqYkdjcE1MLmpzIjtpbXBvcnR7cyBhcyB0fWZyb20iLi9pbmRleC1DQmV5NktWWi5qcyI7dmFyIG49dCgpO2Z1bmN0aW9uIHIoKXtyZXR1cm4oMCxuLmpzeCkoZSx7fSl9ZXhwb3J0e3IgYXMgY29tcG9uZW50fTs="}, "/assets/app-EjbGcpML.js": {"ct": "text/javascript; charset=utf-8", "b64": ""}, "/assets/admin-DE05ol_Q.js": {"ct": "text/javascript; charset=utf-8", "b64": ""}, "/assets/legal-CCmJzFx0.js": {"ct": "text/javascript; charset=utf-8", "b64": ""}, "/__grok/manifest.webmanifest": {"ct": "application/manifest+json", "b64": ""}, "/__grok/icon-180.png": {"ct": "image/png", "b64": ""}};
const port = parseInt(process.env.PORT || "8080", 10);

function send(res, status, body, ctype, cache) {
  res.writeHead(status, {
    "Content-Type": ctype,
    "Content-Length": body.length,
    "Cache-Control": cache,
  });
  res.end(body);
}

const server = http.createServer((req, res) => {
  try {
    let path = decodeURIComponent(new URL(req.url, "http://x").pathname);
    if (path === "/") path = "/index.html";
    const hit = FILES[path];
    if (hit) {
      const body = Buffer.from(hit.b64, "base64");
      const cache = path.startsWith("/assets/")
        ? "public, max-age=31536000, immutable"
        : "public, max-age=300";
      return send(res, 200, body, hit.ct, cache);
    }
    if (/\.[a-zA-Z0-9]{1,8}$/.test(path)) {
      return send(res, 404, Buffer.from("Not found"), "text/plain", "no-store");
    }
    // SPA fallback
    const idx = FILES["/index.html"];
    return send(res, 200, Buffer.from(idx.b64, "base64"), idx.ct, "public, max-age=300");
  } catch (e) {
    return send(res, 500, Buffer.from("Server error"), "text/plain", "no-store");
  }
});
server.listen(port, "0.0.0.0", () => console.log("quiltbee listening on " + port));
